const input = $input.all()[0].json;

const industryTags = (input.industry_vertical || '').split(',').map(t => t.trim().toLowerCase()).filter(Boolean);

const stageMap = {
  'pre-seed': 'pre_seed',
  'preseed': 'pre_seed',
  'seed': 'seed',
  'series a': 'series_a',
  'series b': 'series_b',
  'series c+': 'series_c_plus',
  'growth': 'growth'
};
const normalizedStage = stageMap[(input.funding_stage || '').toLowerCase()] || input.funding_stage;

const fundingAmount = parseFloat((input.funding_amount_needed || '0').toString().replace(/[^0-9.]/g, ''));

const geoPrefs = (input.geographic_preferences || input.location || '').split(',').map(g => g.trim()).filter(Boolean);

const eventTypes = (input.preferred_event_types || '').split(',').map(e => e.trim().toLowerCase()).filter(Boolean);

const searchKeywords = [
  ...industryTags,
  normalizedStage,
  'investor',
  'venture capital',
  'angel investor',
  'startup',
  ...(input.startup_description || '').split(' ').filter(w => w.length > 5).slice(0, 5).map(w => w.toLowerCase())
].filter(Boolean);

const surveyQna = [
  { question: 'Industry / Vertical', answer: input.industry_vertical || '' },
  { question: 'Funding Stage', answer: input.funding_stage || '' },
  { question: 'Funding Amount Needed', answer: input.funding_amount_needed || '' },
  { question: 'Geographic Preferences', answer: input.geographic_preferences || '' },
  { question: 'Founder Background', answer: input.founder_background || '' },
  { question: 'Startup Description', answer: input.startup_description || '' },
  { question: 'Traction Metrics', answer: input.traction_metrics || '' },
  { question: 'LinkedIn Access Method', answer: input.linkedin_access_method || '' },
  { question: 'LinkedIn Token', answer: '***REDACTED***' },
  { question: 'Location', answer: input.location || '' },
  { question: 'Preferred Event Types', answer: input.preferred_event_types || '' }
];

const founderProfile = {
  founder_id: input.founder_id || `founder_${Date.now()}`,
  industry_tags: industryTags,
  funding_stage: normalizedStage,
  funding_amount_needed: fundingAmount,
  geo_preferences: geoPrefs,
  background: input.founder_background || '',
  startup_description: input.startup_description || '',
  traction_metrics: input.traction_metrics || '',
  linkedin_credentials: {
    method: input.linkedin_access_method || 'automation',
    token: input.linkedin_token || ''
  },
  location: input.location || '',
  preferred_event_types: eventTypes,
  search_keywords: [...new Set(searchKeywords)]
};

return [{
  json: {
    status: 'success',
    founder_profile: founderProfile,
    survey_qna: surveyQna
  }
}];
